    projAll: "Alle Projekte",
    prj_sc_tag: "Eigenes Rollenspiel schreiben und als Emotes mit echten Charakteranimationen aufführen.",
    prj_sc_intro: "StoryCaster macht aus einer Geschichte, einer Rede oder einer ganzen Szene /emote-Zeilen, die im Takt eines Timers ablaufen, während Ihr Charakter sie spielt: eine Verbeugung, ein Winken, ein Lachen, ein Kniefall. Ihre Worte, Ihr Timing, und kein Tippen mitten im entscheidenden Moment.",
    prj_sc_logoAlt: "StoryCaster-Logo: eine leuchtende offene Hand, die aus violettem Rauch greift",
    prj_sc_f1t: "Ihre Worte, aufgeführt",
    prj_sc_f1: "Rollenspiel einfügen und es wird zu Emotes mit Timer oder Zeile für Zeile per Deliver-Taste, mit 18 Animationsknöpfen und Tags wie [bow] im Text.",
    prj_sc_f2t: "Die Lore-Bibliothek",
    prj_sc_f2: "Über 60 fertige Sammlungen mit je 50+ Zeilen für jede Klasse, jedes Volk, jede Fraktion, jeden Beruf, jeden Feiertag und jeden Anlass, mit einem Klick spielbereit.",
    prj_sc_f3t: "Duette, Szenen und Entscheidungen",
    prj_sc_f3: "Ein Skript in Rollen für mehrere Spieler aufteilen und synchron halten, in Szenen gliedern, Stimmungen setzen und Verzweigungen zum Auswählen schreiben.",
    prj_sc_f4t: "Bühnenthemen",
    prj_sc_f4: "Piraten (701 Zeilen und ein Piratenakzent), Liebe, Krieg, Frieden, schnelle Dungeon-Sätze für die Gruppe und ein frecher, aber nie expliziter After-Dark-Tab hinter einer Altersabfrage.",
    prj_sc_f5t: "Spielerfokus und Ideen",
    prj_sc_f5: "Andere Spieler ab und zu in Ihre Zeilen einbinden und ihr Total-RP-3- oder MyRolePlay-Profil für Gesprächseinstiege auslesen.",
    prj_sc_f6t: "Bequem gemacht",
    prj_sc_f6: "Ein Mini-Player mit ausklappbaren Studio-, Library- und Stage-Bereichen, Kompaktmodus, Tastenbelegung, Sicherung und Wiederherstellung sowie Minimap-Knopf.",
    prj_sc_fair: "StoryCaster sendet nie schneller als eine Zeile alle 15 Sekunden oder vier pro Minute, damit Ihr Rollenspiel innerhalb der Chatregeln des Spiels bleibt.",
    prj_sc_alt1: "Die StoryCaster-Konsole spielt ein Jäger-Skript, mit geöffneten Bereichen Studio, Library und Stage",
    prj_sc_alt2: "Die Lore-Bibliothek mit fertigen Skripten für jede Klasse, jedes Volk und jeden Anlass",
    prj_sc_alt3: "Das Piratenthema mit seinen Kategorien von Zeilen",
    prj_sc_alt4: "Der Ideen-Tab schlägt Einstiege aus dem Profil eines anderen Spielers vor",
    prj_mbp_tag: "Angeln mit einer Taste, mit Live-Preisen aus dem Auktionshaus und einer Rangliste für alle Angler.",
    prj_mbp_intro: "Master Baiter Pro macht Angeln zu einer Taste und jeden Fisch zu einer Zahl. Taste drücken zum Auswerfen, noch einmal drücken, wenn der Schwimmer platscht, und der Fang erscheint mit Symbol und Auktionshauspreis, während ein Goldzähler Ihre Ausbeute hochzählt.",
    prj_mbp_logoAlt: "Master-Baiter-Pro-Logo: ein grinsender einäugiger Wurm neben einem goldenen Angelhaken",
    prj_mbp_f1t: "Angeln mit einer Taste",
    prj_mbp_f1: "Dieselbe Taste wirft aus und holt ein. Einmal belegt, wird Angeln zum Rhythmus statt zur Pflicht.",
    prj_mbp_f2t: "Jeder Fisch mit Preis",
    prj_mbp_f2: "Es schlägt den Auktionshauspreis von allem nach, was Sie fangen (oder nutzt Auctionator bzw. TSM), und zeigt Ausbeute und Gold pro Stunde beim Angeln.",
    prj_mbp_f3t: "Ihre Top fünf",
    prj_mbp_f3: "Ihre fünf wertvollsten Fänge stehen als Gegenstandssymbole im Fenster, mit Preisen beim Darüberfahren, für die Sitzung oder für immer.",
    prj_mbp_f4t: "Eine Live-Rangliste",
    prj_mbp_f4: "Jede Kopie findet die anderen, zeigt, wer gerade angelt, und ordnet alle nach Fängen, bestem Fang, dieser Woche und Gold pro Stunde.",
    prj_mbp_f5t: "Rekorde und Jackpots",
    prj_mbp_f5: "Serien, Fangquote, persönliche Rekorde und ein Hinweis, wenn etwas Seltenes oder Wertvolles anbeißt.",
    prj_mbp_f6t: "Zwei Editionen",
    prj_mbp_f6: "Master Baiter Pro für Midnight und Master Bait Forever für World of Warcraft: Forever, mit eigener Rangliste.",
    prj_mbp_fair: "Es ist ein Helfer, kein Bot: Jeder Wurf und jedes Einholen beginnt mit Ihrem eigenen Tastendruck. Es bewegt nie Ihren Charakter und liest nie den Speicher des Spiels.",
    prj_mbp_alt1: "Das Master-Baiter-Pro-Fenster neben einem Schwimmer im Wasser, mit Ausbeute, Gold pro Stunde und besten Fängen",
