    aboutTitle: "Über uns",
    aboutLead: "Ein Engineering-Unternehmen in Osaka, das mit Sorgfalt zuverlässige Technik baut.",
    aboutWhoTitle: "Wer wir sind",
    aboutWho1: "Tenshi Systems Engineering ist ein Engineering- und Technologieunternehmen mit Sitz in Osaka, Japan. Wir helfen Organisationen, die Systeme zu planen, zu bauen und zu betreiben, auf die sie sich verlassen, von individueller Software und Websites bis zu Hosting, KI und Branding.",
    aboutWho2: "Gute Technik sollte zuverlässig, verständlich und langlebig sein. Deshalb nehmen wir uns Zeit zum Zuhören, erklären unsere Entscheidungen klar und bleiben auch lange nach dem Start an Ihrer Seite.",
    aboutNameTitle: "Unser Name",
    aboutName: "Tenshi (天使) bedeutet auf Japanisch „Engel“. Für uns ist das ein Versprechen: jedes Projekt und jeden Kunden mit Sorgfalt zu begleiten, vom ersten Gespräch bis lange nach dem Start.",
    aboutValuesTitle: "Was uns wichtig ist",
    val1Title: "Zuverlässigkeit",
    val1Text: "Systeme, die funktionieren, gebaut mit bewährten Methoden und sorgfältigen Tests.",
    val2Title: "Handwerk",
    val2Text: "Liebe zum Detail in jeder Codezeile, jedem Layout und jeder Übergabe.",
    val3Title: "Partnerschaft",
    val3Text: "Together Best Cooperation: Wir arbeiten mit Ihrem Team, nicht nur für es.",
    val4Title: "Klarheit",
