    projectsIntro: "العمل للعملاء نصف ما نقوم به فقط. مشاريعنا الخاصة هي المكان الذي نجرّب فيه أفكارًا جديدة ونصقل فيه حرفتنا ونردّ فيه الجميل للمجتمعات التي نحبها. يصمم فريقنا كل مشروع ويبرمجه ويختبره ويدعمه بنفسه.",
