    prj_sc_tag: "اكتب لعب الأدوار الخاص بك وأدّه بتعابير مع حركات حقيقية لشخصيتك.",
    prj_sc_intro: "يحوّل StoryCaster قصة أو خطابًا أو مشهدًا كاملًا إلى أسطر ‎/emote‎ تُعرض وفق مؤقّت بينما تؤدي شخصيتك الدور: انحناءة، تلويحة، ضحكة، ركوع. كلماتك وتوقيتك، دون كتابة في منتصف اللحظة المهمة.",
    prj_sc_logoAlt: "شعار StoryCaster: يد مفتوحة مضيئة تمتد من دخان بنفسجي",
    prj_sc_f1t: "كلماتك على المسرح",
    prj_sc_f1: "الصق نصك فيتحول إلى تعابير بمؤقّت، أو سطرًا بسطر بزر Deliver واحد، مع 18 زرًا للحركات ووسوم مثل [bow] داخل النص.",
    prj_sc_f2t: "مكتبة الحكايات",
    prj_sc_f2: "أكثر من 60 مجموعة جاهزة، في كل منها أكثر من 50 سطرًا، لكل فئة وعرق وفصيل ومهنة وعيد ومناسبة، جاهزة للأداء بنقرة.",
    prj_sc_f3t: "ثنائيات ومشاهد وخيارات",
    prj_sc_f3: "قسّم النص إلى أدوار لعدة لاعبين مع مزامنتها، وقسّمه إلى مشاهد، وحدّد المزاج، واكتب تفرعات يختار فيها المشاهد الطريق.",
    prj_sc_f4t: "سمات المسرح",
    prj_sc_f4: "القراصنة (701 سطر ولهجة قرصان)، والحب، والحرب، والسلام، وعبارات سريعة للمجموعة في الأبراج المحصنة، وتبويب After Dark مشاكس لكنه غير فاضح أبدًا خلف تحقق من العمر.",
    prj_sc_f5t: "التركيز على اللاعبين والأفكار",
    prj_sc_f5: "أدخل لاعبًا آخر في أسطرك بين حين وآخر، واقرأ ملفه في Total RP 3 أو MyRolePlay لتحصل على افتتاحيات واقتراحات.",
    prj_sc_f6t: "مصمم للراحة",
    prj_sc_f6: "مشغّل صغير تنزلق منه لوحات Studio وLibrary وStage، ووضع مضغوط، واختصارات لوحة المفاتيح، ونسخ احتياطي واستعادة، وزر على الخريطة المصغّرة.",
    prj_sc_fair: "لا ينشر StoryCaster أسرع من سطر كل 15 ثانية أو أربعة أسطر في الدقيقة، فيبقى لعب الأدوار ضمن قواعد الدردشة في اللعبة.",
    prj_sc_alt1: "وحدة تحكم StoryCaster تؤدي نص صيّاد، ولوحات Studio وLibrary وStage مفتوحة",
    prj_sc_alt2: "مكتبة الحكايات بنصوص جاهزة لكل فئة وعرق ومناسبة",
    prj_sc_alt3: "لوحة سمة القراصنة بفئات أسطرها",
    prj_sc_alt4: "تبويب الأفكار يقترح افتتاحيات من ملف لاعب آخر",
    prj_mbp_tag: "صيد بزر واحد مع أسعار دار المزاد المباشرة ولوحة صدارة لكل الصيادين.",
    prj_mbp_intro: "يحوّل Master Baiter Pro الصيد إلى زر واحد وكل سمكة إلى رقم. اضغط الزر لترمي الصنارة، واضغطه مجددًا عندما يرشّ العوّام الماء، فتظهر الصيدة بأيقونتها وسعرها في دار المزاد بينما يعدّ عدّاد الذهب حصيلتك.",
    prj_mbp_logoAlt: "شعار Master Baiter Pro: دودة بعين واحدة تبتسم بجانب خطّاف صيد ذهبي",
    prj_mbp_f1t: "صيد بزر واحد",
    prj_mbp_f1: "الزر نفسه يرمي ويسحب. عيّنه مرة واحدة ويصبح الصيد إيقاعًا لا عبئًا.",
    prj_mbp_f2t: "لكل سمكة سعر",
    prj_mbp_f2: "يبحث عن سعر كل ما تصطاده في دار المزاد (أو يستخدم Auctionator أو TSM)، ويعرض حصيلتك والذهب في الساعة أثناء الصيد.",
    prj_mbp_f3t: "أفضل خمس صيدات",
    prj_mbp_f3: "أثمن خمس صيدات تظهر في اللوحة بأيقوناتها مع السعر عند المرور بالمؤشر، للجلسة الحالية أو لكل الأوقات.",
    prj_mbp_f4t: "لوحة صدارة مباشرة",
    prj_mbp_f4: "كل نسخة تعثر على النسخ الأخرى، وتُظهر من يصطاد الآن، وترتّب الجميع حسب عدد الصيدات وأفضل صيدة وهذا الأسبوع والذهب في الساعة.",
    prj_mbp_f5t: "أرقام قياسية وجوائز كبرى",
    prj_mbp_f5: "سلاسل متتالية، ونسبة النجاح، وأرقام شخصية، وتنبيه عندما يعلق شيء نادر أو ثمين بالطُّعم.",
    prj_mbp_f6t: "إصداران",
    prj_mbp_f6: "Master Baiter Pro للعبة Midnight، وMaster Bait Forever للعبة World of Warcraft: Forever بلوحة صدارة خاصة به.",
    prj_mbp_fair: "إنه مساعد وليس روبوتًا: كل رمية وكل سحبة تبدأ بضغطة زر منك. لا يحرّك شخصيتك أبدًا ولا يقرأ ذاكرة اللعبة.",
    prj_mbp_alt1: "لوحة Master Baiter Pro بجانب عوّام في الماء، تعرض حصيلة الجلسة والذهب في الساعة وأفضل الصيدات",
