    aboutWho1: "تنشی سیستمز انجینیرینگ یک شرکت مهندسی و فناوری مستقر در اوساکا، ژاپن است. ما به سازمان‌ها کمک می‌کنیم سیستم‌هایی را که به آن‌ها وابسته‌اند برنامه‌ریزی کنند، بسازند و اداره کنند؛ از نرم‌افزار و وب‌سایت سفارشی تا میزبانی، هوش مصنوعی و برندسازی.",
    aboutWho2: "باور داریم فناوری خوب باید قابل اعتماد، قابل فهم و ماندگار باشد. به همین دلیل وقت می‌گذاریم تا بشنویم، تصمیم‌هایمان را روشن توضیح می‌دهیم و تا مدت‌ها پس از راه‌اندازی کنارتان می‌مانیم.",
    aboutNameTitle: "نام ما",
    aboutName: "«تنشی» (天使) در زبان ژاپنی به معنای «فرشته» است. این برای ما یک عهد است: مراقبت از هر پروژه و هر مشتری با دقت، از نخستین گفت‌وگو تا مدت‌ها پس از راه‌اندازی.",
